package mdn.jh.automation.devices.mqtt;import java.util.Iterator;import org.w3c.dom.Node;import mdn.jh.automation.device.DataSinkHandler;import mdn.jh.automation.io.sink.DataSink;
public class MqttDataSinkHandler extends DataSinkHandler{private static final long serialVersionUID=1L;private final MqttBrokerDevice device;public MqttDataSinkHandler(MqttBrokerDevice d){device=d;}public MqttDataSinkHandler(MqttBrokerDevice d,Node n)throws Exception{this(d);initDataComponent(n);}@Override public boolean initDataComponent(Node n)throws Exception{boolean r=super.initDataComponent(n);for(Iterator<DataSink>i=getMyDataSinks().iterator();i.hasNext();)((MqttDataSink)i.next()).setDevice(device);return r;}@Override protected String getDataSinkDetail(){return device.getName();}}
